const listActivePricingRates = `-- name: ListActivePricingRates :many
WITH ranked_rates AS (
    SELECT
        r.plan_key,
        p.name AS plan_name,
        p.currency,
        r.resource,
        r.unit,
        r.price_usd,
        r.effective_from,
        row_number() OVER (
            PARTITION BY r.resource, r.unit
            ORDER BY r.effective_from DESC, r.created_at DESC, r.id DESC
        ) AS rate_rank
    FROM pricing_rate r
    JOIN pricing_plan p ON p.key = r.plan_key
    WHERE r.plan_key = $1
      AND p.active
      AND r.effective_from <= now()
      AND (r.effective_to IS NULL OR r.effective_to > now())
)
SELECT
    plan_key,
    plan_name,
    currency,
    resource,
    unit,
    price_usd,
    effective_from
FROM ranked_rates
WHERE rate_rank = 1
ORDER BY resource, unit
`

type ListActivePricingRatesRow struct {
	PlanKey       string         `json:"plan_key"`
	PlanName      string         `json:"plan_name"`
	Currency      string         `json:"currency"`
	Resource      string         `json:"resource"`
	Unit          string         `json:"unit"`
	PriceUsd      pgtype.Numeric `json:"price_usd"`
	EffectiveFrom time.Time      `json:"effective_from"`
}

func (q *Queries) ListActivePricingRates(ctx context.Context, planKey string) ([]ListActivePricingRatesRow, error) {
	rows, err := q.db.Query(ctx, listActivePricingRates, planKey)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListActivePricingRatesRow{}
	for rows.Next() {
		var i ListActivePricingRatesRow
		if err := rows.Scan(
			&i.PlanKey,
			&i.PlanName,
			&i.Currency,
			&i.Resource,
			&i.Unit,
			&i.PriceUsd,
			&i.EffectiveFrom,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listActivePricingRatesForTeam = `-- name: ListActivePricingRatesForTeam :many
WITH selected_plan AS (
    SELECT COALESCE((
        SELECT tpp.plan_key
        FROM team_pricing_plan tpp
        JOIN pricing_plan p ON p.key = tpp.plan_key
        WHERE tpp.team_id = $1
          AND p.active
          AND tpp.effective_from <= $2::timestamptz
          AND (tpp.effective_to IS NULL OR tpp.effective_to > $2::timestamptz)
        ORDER BY tpp.effective_from DESC
        LIMIT 1
    ), 'payg')::text AS plan_key
),
ranked_rates AS (
    SELECT
        r.plan_key,
        p.name AS plan_name,
        p.currency,
        r.resource,
        r.unit,
        r.price_usd,
        r.effective_from,
        row_number() OVER (
            PARTITION BY r.resource, r.unit
            ORDER BY r.effective_from DESC, r.created_at DESC, r.id DESC
        ) AS rate_rank
    FROM selected_plan sp
    JOIN pricing_rate r ON r.plan_key = sp.plan_key
    JOIN pricing_plan p ON p.key = r.plan_key
    WHERE p.active
      AND r.effective_from <= $2::timestamptz
      AND (r.effective_to IS NULL OR r.effective_to > $2::timestamptz)
)
SELECT
    plan_key,
    plan_name,
    currency,
    resource,
    unit,
    price_usd,
    effective_from
FROM ranked_rates
WHERE rate_rank = 1
ORDER BY resource, unit
`

