const upsertTeamBillingUsage = `-- name: UpsertTeamBillingUsage :one
WITH compute AS (
    SELECT
        COALESCE(SUM(
            EXTRACT(EPOCH FROM (
                LEAST(COALESCE(i.ended_at, now()), $1)
                - GREATEST(i.started_at, $2)
            )) * i.vcpu_count
        ), 0)::numeric AS vcpu_seconds,
        COALESCE(SUM(
            EXTRACT(EPOCH FROM (
                LEAST(COALESCE(i.ended_at, now()), $1)
                - GREATEST(i.started_at, $2)
            )) * i.memory_mib
        ), 0)::numeric AS memory_mib_seconds
    FROM sandbox_compute_billing_interval i
    WHERE i.team_id = $3
      AND $2 < LEAST(now(), $1)
      AND i.started_at < LEAST(now(), $1)
      AND COALESCE(i.ended_at, LEAST(now(), $1)) > $2
),
artifact_bounds AS (
    SELECT
        s.id,
        s.team_id,
        s.snapshot_id,
        s.template_id,
        s.base_path,
        s.delta_path,
        s.destroyed_at,
        first_interval.started_at AS billing_started_at
    FROM sandbox s
    LEFT JOIN LATERAL (
        SELECT MIN(i.started_at) AS started_at
        FROM sandbox_storage_interval i
        WHERE i.sandbox_id = s.id
          AND i.team_id = s.team_id
    ) first_interval ON true
    WHERE s.team_id = $3
      AND first_interval.started_at IS NOT NULL
      AND first_interval.started_at < LEAST(now(), $1)
      AND s.created_at < LEAST(now(), $1)
      AND COALESCE(s.destroyed_at, LEAST(now(), $1)) > $2
),
artifact_storage AS (
    SELECT FLOOR(COALESCE(SUM(ar.artifact_mib * EXTRACT(EPOCH FROM (upper(r) - lower(r)))), 0))::numeric AS mib_seconds
    FROM (
        SELECT p.path,
               MAX(COALESCE(NULLIF(am.allocated_bytes, 0), 0))::numeric / 1048576.0 AS artifact_mib,
               range_agg(tstzrange(GREATEST(s.billing_started_at, $2), LEAST(COALESCE(s.destroyed_at, now()), $1), '[)')) AS retained_ranges
        FROM artifact_bounds s
        LEFT JOIN template t ON t.id = s.template_id
        CROSS JOIN LATERAL unnest(ARRAY[s.base_path, s.delta_path, CASE WHEN s.base_path IS NULL AND s.delta_path IS NULL THEN t.rootfs_path END]) AS p(path)
        LEFT JOIN artifact_manifest am ON (am.snapshot_id = s.snapshot_id OR am.template_id = t.id)
          AND am.path = p.path
        WHERE p.path IS NOT NULL
        GROUP BY p.path
    ) ar
    CROSS JOIN LATERAL unnest(ar.retained_ranges) AS ranges(r)
),
storage AS (
    SELECT COALESCE(SUM(
        EXTRACT(EPOCH FROM (
            LEAST(COALESCE(i.ended_at, now()), $1)
            - GREATEST(i.started_at, $2)
        )) * i.disk_mib
    ), 0)::numeric + COALESCE(MAX(artifact_storage.mib_seconds), 0) AS storage_mib_seconds
    FROM artifact_storage
    LEFT JOIN sandbox_storage_interval i ON
      i.team_id = $3
      AND $2 < LEAST(now(), $1)
      AND i.started_at < LEAST(now(), $1)
      AND COALESCE(i.ended_at, LEAST(now(), $1)) > $2
),
usage AS (
    SELECT
        $3::uuid AS team_id,
        $2::timestamptz AS period_start,
        $1::timestamptz AS period_end,
        compute.vcpu_seconds,
        compute.memory_mib_seconds,
        storage.storage_mib_seconds
    FROM compute, storage
),
upserted AS (
    INSERT INTO team_billing_usage (
        team_id, period_start, period_end,
        vcpu_seconds, memory_mib_seconds, storage_mib_seconds
    )
    SELECT
        usage.team_id,
        usage.period_start,
        usage.period_end,
        usage.vcpu_seconds,
        usage.memory_mib_seconds,
        usage.storage_mib_seconds
    FROM usage
    WHERE NOT EXISTS (
        SELECT 1
        FROM team_billing_period p
        WHERE p.team_id = usage.team_id
          AND p.period_start = usage.period_start
          AND p.period_end = usage.period_end
          AND (
              p.status IN ('exported', 'finalized')
              OR p.exported_at IS NOT NULL
              OR p.finalized_at IS NOT NULL
          )
    )
    ON CONFLICT (team_id, period_start, period_end) DO UPDATE
    SET vcpu_seconds = EXCLUDED.vcpu_seconds,
        memory_mib_seconds = EXCLUDED.memory_mib_seconds,
        storage_mib_seconds = EXCLUDED.storage_mib_seconds,
        updated_at = now()
    WHERE team_billing_usage.finalized_at IS NULL
      AND team_billing_usage.exported_at IS NULL
    RETURNING
        team_id, period_start, period_end,
        vcpu_seconds, memory_mib_seconds, storage_mib_seconds,
        finalized_at, exported_at, updated_at
),
immutable_existing AS (
    SELECT
        existing.team_id,
        existing.period_start,
        existing.period_end,
        existing.vcpu_seconds,
        existing.memory_mib_seconds,
        existing.storage_mib_seconds,
        existing.finalized_at,
        existing.exported_at,
        existing.updated_at
    FROM team_billing_usage existing
    JOIN usage
      ON usage.team_id = existing.team_id
     AND usage.period_start = existing.period_start
     AND usage.period_end = existing.period_end
    WHERE NOT EXISTS (SELECT 1 FROM upserted)
      AND (
          existing.exported_at IS NOT NULL
          OR existing.finalized_at IS NOT NULL
      )
)
SELECT team_id, period_start, period_end, vcpu_seconds, memory_mib_seconds, storage_mib_seconds, finalized_at, exported_at, updated_at FROM upserted
UNION ALL
SELECT team_id, period_start, period_end, vcpu_seconds, memory_mib_seconds, storage_mib_seconds, finalized_at, exported_at, updated_at FROM immutable_existing
LIMIT 1
`

type UpsertTeamBillingUsageParams struct {
	PeriodEnd   pgtype.Timestamptz `json:"period_end"`
	PeriodStart pgtype.Timestamptz `json:"period_start"`
	TeamID      uuid.UUID          `json:"team_id"`
}

type UpsertTeamBillingUsageRow struct {
	TeamID            uuid.UUID          `json:"team_id"`
	PeriodStart       time.Time          `json:"period_start"`
	PeriodEnd         time.Time          `json:"period_end"`
	VcpuSeconds       pgtype.Numeric     `json:"vcpu_seconds"`
	MemoryMibSeconds  pgtype.Numeric     `json:"memory_mib_seconds"`
	StorageMibSeconds pgtype.Numeric     `json:"storage_mib_seconds"`
	FinalizedAt       pgtype.Timestamptz `json:"finalized_at"`
	ExportedAt        pgtype.Timestamptz `json:"exported_at"`
	UpdatedAt         time.Time          `json:"updated_at"`
}

// Recomputes a team's period rollup from raw intervals. Exported/finalized
// rows are immutable so a billing export cannot be silently rewritten.
func (q *Queries) UpsertTeamBillingUsage(ctx context.Context, arg UpsertTeamBillingUsageParams) (UpsertTeamBillingUsageRow, error) {
	row := q.db.QueryRow(ctx, upsertTeamBillingUsage, arg.PeriodEnd, arg.PeriodStart, arg.TeamID)
	var i UpsertTeamBillingUsageRow
	err := row.Scan(
		&i.TeamID,
		&i.PeriodStart,
		&i.PeriodEnd,
		&i.VcpuSeconds,
		&i.MemoryMibSeconds,
		&i.StorageMibSeconds,
		&i.FinalizedAt,
		&i.ExportedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertTeamBillingUsageHour = `-- name: UpsertTeamBillingUsageHour :one
WITH compute AS (
    SELECT
        COALESCE(SUM(
            EXTRACT(EPOCH FROM (
                LEAST(COALESCE(i.ended_at, billing_request_now()), $1)
                - GREATEST(i.started_at, $2)
            )) * i.vcpu_count
        ), 0)::numeric AS vcpu_seconds,
        COALESCE(SUM(
            EXTRACT(EPOCH FROM (
                LEAST(COALESCE(i.ended_at, billing_request_now()), $1)
                - GREATEST(i.started_at, $2)
            )) * i.memory_mib
        ), 0)::numeric AS memory_mib_seconds
    FROM sandbox_compute_billing_interval i
    WHERE i.team_id = $3
      AND i.started_at < $1
      AND $2 < LEAST(billing_request_now(), $1)
      AND COALESCE(i.ended_at, LEAST(billing_request_now(), $1)) > $2
),
artifact_bounds AS (
    SELECT
        s.id,
        s.team_id,
        s.snapshot_id,
        s.template_id,
        s.base_path,
        s.delta_path,
        s.destroyed_at,
        first_interval.started_at AS billing_started_at
    FROM sandbox s
    LEFT JOIN LATERAL (
        SELECT MIN(i.started_at) AS started_at
        FROM sandbox_storage_interval i
        WHERE i.sandbox_id = s.id
          AND i.team_id = s.team_id
    ) first_interval ON true
    WHERE s.team_id = $3
      AND first_interval.started_at IS NOT NULL
      AND first_interval.started_at < LEAST(billing_request_now(), $1)
      AND s.created_at < LEAST(billing_request_now(), $1)
      AND COALESCE(s.destroyed_at, LEAST(billing_request_now(), $1)) > $2
),
artifact_storage AS (
    SELECT FLOOR(COALESCE(SUM(ar.artifact_mib * EXTRACT(EPOCH FROM (upper(r) - lower(r)))), 0))::numeric AS mib_seconds
    FROM (
        SELECT p.path,
               MAX(COALESCE(NULLIF(am.allocated_bytes, 0), 0))::numeric / 1048576.0 AS artifact_mib,
               range_agg(tstzrange(GREATEST(s.billing_started_at, $2), LEAST(COALESCE(s.destroyed_at, billing_request_now()), $1), '[)')) AS retained_ranges
        FROM artifact_bounds s
        LEFT JOIN template t ON t.id = s.template_id
        CROSS JOIN LATERAL unnest(ARRAY[s.base_path, s.delta_path, CASE WHEN s.base_path IS NULL AND s.delta_path IS NULL THEN t.rootfs_path END]) AS p(path)
        LEFT JOIN artifact_manifest am ON (am.snapshot_id = s.snapshot_id OR am.template_id = t.id)
          AND am.path = p.path
        WHERE p.path IS NOT NULL
        GROUP BY p.path
    ) ar
    CROSS JOIN LATERAL unnest(ar.retained_ranges) AS ranges(r)
),
storage AS (
    SELECT COALESCE(SUM(
        EXTRACT(EPOCH FROM (
            LEAST(COALESCE(i.ended_at, billing_request_now()), $1)
            - GREATEST(i.started_at, $2)
        )) * i.disk_mib
    ), 0)::numeric + COALESCE(MAX(artifact_storage.mib_seconds), 0) AS storage_mib_seconds
    FROM artifact_storage
    LEFT JOIN sandbox_storage_interval i ON
      i.team_id = $3
      AND i.started_at < $1
      AND $2 < LEAST(billing_request_now(), $1)
      AND COALESCE(i.ended_at, LEAST(billing_request_now(), $1)) > $2
),
usage AS (
    SELECT
        $3::uuid AS team_id,
        $2::timestamptz AS hour_start,
        $1::timestamptz AS hour_end,
        compute.vcpu_seconds,
        compute.memory_mib_seconds,
        storage.storage_mib_seconds
    FROM compute, storage
    WHERE feature_enabled('billing_hourly_rollups', $3::uuid)
)
INSERT INTO team_billing_usage_hourly (
    team_id, hour_start, hour_end,
    vcpu_seconds, memory_mib_seconds, storage_mib_seconds
)
SELECT
    usage.team_id,
    usage.hour_start,
    usage.hour_end,
    usage.vcpu_seconds,
    usage.memory_mib_seconds,
    usage.storage_mib_seconds
FROM usage
ON CONFLICT (team_id, hour_start) DO UPDATE
SET hour_end = EXCLUDED.hour_end,
    vcpu_seconds = EXCLUDED.vcpu_seconds,
    memory_mib_seconds = EXCLUDED.memory_mib_seconds,
    storage_mib_seconds = EXCLUDED.storage_mib_seconds,
    updated_at = now()
RETURNING team_id, hour_start, hour_end, vcpu_seconds, memory_mib_seconds, storage_mib_seconds, updated_at
`

type UpsertTeamBillingUsageHourParams struct {
	HourEnd   pgtype.Timestamptz `json:"hour_end"`
	HourStart pgtype.Timestamptz `json:"hour_start"`
	TeamID    uuid.UUID          `json:"team_id"`
}

func (q *Queries) UpsertTeamBillingUsageHour(ctx context.Context, arg UpsertTeamBillingUsageHourParams) (TeamBillingUsageHourly, error) {
	row := q.db.QueryRow(ctx, upsertTeamBillingUsageHour, arg.HourEnd, arg.HourStart, arg.TeamID)
	var i TeamBillingUsageHourly
	err := row.Scan(
		&i.TeamID,
		&i.HourStart,
		&i.HourEnd,
		&i.VcpuSeconds,
		&i.MemoryMibSeconds,
		&i.StorageMibSeconds,
		&i.UpdatedAt,
	)
	return i, err
}
